PRAGMA temp_store=MEMORY;
CREATE TEMP TABLE queries AS SELECT event_time_s, domain, client_ip, client_name, source_id, status, status_code, query_type, query_type_code FROM main.queries;
CREATE INDEX temp.ty ON queries((CAST(event_time_s AS INTEGER) / 900), source_id, status, status_code, client_ip, client_name, domain, query_type, query_type_code, event_time_s);
.timer on
SELECT 'wide', COUNT(*), SUM(n) FROM (SELECT (CAST(event_time_s AS INTEGER) / 900) AS c, source_id, CASE WHEN status IS NULL THEN status_code ELSE CASE upper(status) WHEN 'GRAVITY' THEN 1 WHEN 'FORWARDED' THEN 2 WHEN 'CACHE' THEN 3 WHEN 'REGEX' THEN 4 WHEN 'DENYLIST' THEN 5 ELSE NULL END END AS code, client_ip, client_name, domain, query_type, COUNT(*) AS n FROM temp.queries WHERE NOT ((source_id = '025d7d12-6890-4e10-96a9-316bd22aa73e' AND event_time_s < 1792972800) OR (source_id = 'd7f6bfd0-bb5e-4d63-8f90-5700bcba0bdb' AND event_time_s < 1792972800)) AND event_time_s >= 1792972800 AND event_time_s < 1793041626 AND (CAST(event_time_s AS INTEGER) / 900) >= 1992192 AND (CAST(event_time_s AS INTEGER) / 900) <= 1992268 GROUP BY c, source_id, status, status_code, client_ip, client_name, domain, query_type, query_type_code LIMIT 200001);
SELECT 'timeline', COUNT(*) FROM (SELECT (CAST(event_time_s AS INTEGER) / 900) AS c, source_id, CASE WHEN status IS NULL THEN status_code ELSE CASE upper(status) WHEN 'GRAVITY' THEN 1 WHEN 'FORWARDED' THEN 2 WHEN 'CACHE' THEN 3 WHEN 'REGEX' THEN 4 WHEN 'DENYLIST' THEN 5 ELSE NULL END END, COUNT(*) FROM temp.queries WHERE NOT ((source_id = '025d7d12-6890-4e10-96a9-316bd22aa73e' AND event_time_s < 1792972800) OR (source_id = 'd7f6bfd0-bb5e-4d63-8f90-5700bcba0bdb' AND event_time_s < 1792972800)) AND event_time_s >= 1792972800 AND event_time_s < 1793041626 AND (CAST(event_time_s AS INTEGER) / 900) >= 1992192 AND (CAST(event_time_s AS INTEGER) / 900) <= 1992268 GROUP BY c, source_id, status, status_code);
SELECT 'clients', COUNT(*) FROM (SELECT (CAST(event_time_s AS INTEGER) / 900) AS c, source_id, CASE WHEN status IS NULL THEN status_code ELSE CASE upper(status) WHEN 'GRAVITY' THEN 1 WHEN 'FORWARDED' THEN 2 WHEN 'CACHE' THEN 3 WHEN 'REGEX' THEN 4 WHEN 'DENYLIST' THEN 5 ELSE NULL END END, client_ip, client_name, domain, COUNT(*), MIN(event_time_s), MAX(event_time_s) FROM temp.queries WHERE NOT ((source_id = '025d7d12-6890-4e10-96a9-316bd22aa73e' AND event_time_s < 1792972800) OR (source_id = 'd7f6bfd0-bb5e-4d63-8f90-5700bcba0bdb' AND event_time_s < 1792972800)) AND event_time_s >= 1792972800 AND event_time_s < 1793041626 AND (CAST(event_time_s AS INTEGER) / 900) >= 1992192 AND (CAST(event_time_s AS INTEGER) / 900) <= 1992268 GROUP BY c, source_id, status, status_code, client_ip, client_name, domain);
SELECT 'identity', COUNT(*) FROM (SELECT (CAST(event_time_s AS INTEGER) / 900) AS c, source_id, client_ip, client_name FROM temp.queries WHERE NOT ((source_id = '025d7d12-6890-4e10-96a9-316bd22aa73e' AND event_time_s < 1792972800) OR (source_id = 'd7f6bfd0-bb5e-4d63-8f90-5700bcba0bdb' AND event_time_s < 1792972800)) AND event_time_s >= 1792972800 AND event_time_s < 1793041626 AND (CAST(event_time_s AS INTEGER) / 900) >= 1992192 AND (CAST(event_time_s AS INTEGER) / 900) <= 1992268 GROUP BY c, source_id, status, status_code, client_ip, client_name);
SELECT 'identity_distinct', COUNT(*) FROM (SELECT DISTINCT source_id, client_ip, client_name FROM temp.queries WHERE NOT ((source_id = '025d7d12-6890-4e10-96a9-316bd22aa73e' AND event_time_s < 1792972800) OR (source_id = 'd7f6bfd0-bb5e-4d63-8f90-5700bcba0bdb' AND event_time_s < 1792972800)) AND event_time_s >= 1792972800 AND event_time_s < 1793041626 AND (CAST(event_time_s AS INTEGER) / 900) >= 1992192 AND (CAST(event_time_s AS INTEGER) / 900) <= 1992268);
EXPLAIN QUERY PLAN SELECT (CAST(event_time_s AS INTEGER) / 900) AS c, source_id, client_ip, client_name FROM temp.queries WHERE NOT ((source_id = '025d7d12-6890-4e10-96a9-316bd22aa73e' AND event_time_s < 1792972800) OR (source_id = 'd7f6bfd0-bb5e-4d63-8f90-5700bcba0bdb' AND event_time_s < 1792972800)) AND event_time_s >= 1792972800 AND event_time_s < 1793041626 AND (CAST(event_time_s AS INTEGER) / 900) >= 1992192 AND (CAST(event_time_s AS INTEGER) / 900) <= 1992268 GROUP BY c, source_id, status, status_code, client_ip, client_name;
SELECT 'domain_pass', COUNT(*) FROM (SELECT domain, COUNT(*) FROM temp.queries WHERE NOT ((source_id = '025d7d12-6890-4e10-96a9-316bd22aa73e' AND event_time_s < 1792972800) OR (source_id = 'd7f6bfd0-bb5e-4d63-8f90-5700bcba0bdb' AND event_time_s < 1792972800)) AND event_time_s >= 1792972800 AND event_time_s < 1793041626 AND (CAST(event_time_s AS INTEGER) / 900) >= 1992192 AND (CAST(event_time_s AS INTEGER) / 900) <= 1992268 GROUP BY domain);
